To create a simple YAML parser in Go without using third-party libraries, you can follow these steps:

1. Define a `YAMLNode` type as a map to store the parsed data.
2. Implement a `ParseYAML` function that takes a string input and returns a `YAMLNode`.
3. Split the input into lines and pass them to a helper function `parseYAMLLines`.
4. Implement `parseYAMLLines` to process each line, determine its indentation, and build the data structure accordingly.
5. Use a helper function `getIndent` to calculate the indentation level of a line.
6. Implement `parseSimpleValue` to handle scalar values like strings and numbers.

Here's a basic implementation:

```go
type YAMLNode map[string]interface{}

func ParseYAML(input string) YAMLNode {
	lines := strings.Split(input, "\n")
	return parseYAMLLines(lines)
}

func parseYAMLLines(lines []string) YAMLNode {
	root := YAMLNode{}
	currentNode := &root
	for _, line := range lines {
		indent := getIndent(line)
		if indent == 0 {
			currentNode = &root
		} else {
			for indent > 0 {
				currentNode = &(*currentNode)[getKeyName(line)]
				line = strings.TrimSpace(strings.TrimPrefix(line, getKeyName(line)+": "))
				indent = getIndent(line)
			}
		}
		if line == "" {
			continue
		}
		key, value := getKeyValue(line)
		(*currentNode)[key] = parseSimpleValue(value)
	}
	return root
}

func getIndent(s string) int {
	return len(s) - len(strings.TrimLeft(s, " "))
}

func getKeyName(s string) string {
	return strings.SplitN(strings.TrimSpace(s), ":", 2)[0]
}

func getKeyValue(s string) (string, string) {
	parts := strings.SplitN(strings.TrimSpace(s), ":", 2)
	return parts[0], parts[1]
}

func parseSimpleValue(value string) interface{} {
	if strings.HasPrefix(value, "\"") && strings.HasSuffix(value, "\"") {
		return strings.Trim(value, "\"")
	}
	if strings.HasPrefix(value, "[") && strings.HasSuffix(value, "]") {
		return strings.Trim(value, "[]")
	}
	return value
}
```

